                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_1_May2025 as WITH sizeCombsFromInv AS ( SELECT branch_code, REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), 1, POSITION(\'-\', REVERSE(ADDLITEMCODE)) - 1)) AS size, CASE WHEN POSITION(\'-\' IN ADDLITEMCODE) > 0 THEN LEFT(ADDLITEMCODE, LENGTH(ADDLITEMCODE) - LENGTH(REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), 1, POSITION(\'-\', REVERSE(ADDLITEMCODE)) - 1))) - 1) ELSE ADDLITEMCODE END AS sku_group, ADDLITEMCODE, SUM(stock_qty) AS stock_qty, CASE WHEN ADDLITEMCODE LIKE \'SN%\' OR ADDLITEMCODE LIKE \'4MSFR%\' OR ADDLITEMCODE LIKE \'BP%\' THEN \'NA\' WHEN ADDLITEMCODE LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE date = CURRENT_DATE AND ADDLITEMCODE NOT LIKE \'%CB%\' GROUP BY branch_code, size, sku_group, ADDLITEMCODE, size_mapped ), sizeCombsFromSales AS ( SELECT branch_code, sku, sku_group, REVERSE(SUBSTRING(REVERSE(sku), 1, POSITION(\'-\', REVERSE(sku)) - 1)) AS size, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE order_date <= CURRENT_DATE AND sku NOT LIKE \'CB%\' AND marketplace NOT LIKE (\'%SNITCH - WH%\') AND sku NOT LIKE (\'%4MCB%\') GROUP BY branch_code, sku, sku_group, size, size_mapped ), relevant_sku_branches AS ( SELECT DISTINCT branch_code, sku_group FROM sizeCombsFromInv UNION SELECT DISTINCT branch_code, sku_group FROM sizeCombsFromSales ), relevant_sizes AS ( SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromInv UNION SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromSales ), valid_combinations AS ( SELECT rb.branch_code, rs.sku_group, rs.size, rs.size_mapped FROM relevant_sku_branches rb INNER JOIN relevant_sizes rs ON rb.sku_group = rs.sku_group ), sizeExtract AS ( SELECT vc.branch_code, vc.sku_group, vc.size, vc.size_mapped, COALESCE(q1.ADDLITEMCODE, CONCAT(vc.sku_group, \'-\', vc.size)) AS logicusercode, COALESCE(q1.stock_qty, 0) AS stock_qty FROM valid_combinations vc LEFT JOIN sizeCombsFromInv q1 ON vc.branch_code = q1.branch_code AND vc.sku_group = q1.sku_group AND vc.size = q1.size ), sizeExtractPivotUp AS ( SELECT branch_code, sku_group, COALESCE(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END), 0) AS XS_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END), 0) AS S_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END), 0) AS M_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END), 0) AS L_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END), 0) AS XL_units_store, COALESCE(SUM(CASE WHEN size_mapped IN (\'XXL\', \'XXl\', \'2XL\') THEN stock_qty ELSE 0 END), 0) AS XXL_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END), 0) AS XL3_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END), 0) AS XL4_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END), 0) AS XL5_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END), 0) AS XL6_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'7XL\' THEN stock_qty ELSE 0 END), 0) AS XL7_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'8XL\' THEN stock_qty ELSE 0 END), 0) AS XL8_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END), 0) AS NA_units_store FROM sizeExtract GROUP BY branch_code, sku_group ), sizeCount AS ( SELECT branch_code, sku_group, COUNT(DISTINCT CASE WHEN stock_qty > 0 THEN size END) AS num_size_available FROM sizeExtract GROUP BY branch_code, sku_group ), store_priority AS ( SELECT BRANCH_CODE_PRIORITY, BRANCH_NAME_PRIORITY, SHORT_NAME, cast(PRIORITY as integer) as PRIORITY FROM snitch_db.maplemonk.storepriority ), ItemData AS ( WITH sales_data AS ( SELECT branch_code, marketplace, sku, sku_group, REVERSE(SPLIT_PART(REVERSE(sku), \'-\', 1)) AS size, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped, order_date, SUM(suborder_quantity) AS units_sold FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE order_date >= CURRENT_DATE - INTERVAL \'45 DAYS\' AND sku NOT LIKE \'CB%\' AND marketplace not like (\'%SNITCH - WH%\') AND sku not like (\'%4MCB%\') GROUP BY branch_code, sku, sku_group, size, size_mapped, marketplace, order_date ), first_sale AS ( SELECT sku_group, branch_code, MIN(order_date) AS first_sale_date FROM sales_data GROUP BY sku_group, branch_code ), total_sales AS ( SELECT s.branch_code, s.marketplace, s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date, SUM(s.units_sold) AS total_units_sold, DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) AS days_elapsed FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group and s.branch_code = f.branch_code GROUP BY s.branch_code, s.marketplace, s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date ), sales_last_7_days AS ( SELECT s.sku, s.branch_code, SUM(s.units_sold) AS units_sold_last_7_days FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group and s.branch_code = f.branch_code WHERE s.order_date >= CASE WHEN DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) < 7 THEN f.first_sale_date ELSE CURRENT_DATE - INTERVAL \'7 DAYS\' END GROUP BY s.sku,s.branch_code ) SELECT ts.branch_code, ts.marketplace, ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(ts.total_units_sold / NULLIF(ts.days_elapsed, 0), 2) END AS natural_rate_of_sale, COALESCE(sl7.units_sold_last_7_days, 0) AS units_sold_last_7_days, CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END AS days_for_7_day_sales, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(COALESCE(sl7.units_sold_last_7_days, 0) / NULLIF( CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END, 0), 2) END AS seven_day_rate_of_sale FROM total_sales ts LEFT JOIN sales_last_7_days sl7 ON ts.sku = sl7.sku and ts.branch_code = sl7.branch_code GROUP BY ts.branch_code, ts.marketplace, ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, natural_rate_of_sale, units_sold_last_7_days, days_for_7_day_sales, seven_day_rate_of_sale ), CategoryUnitsSold AS ( SELECT branch_code, sku_group, size_mapped, SUM(total_units_sold) AS category_units_sold FROM ItemData GROUP BY branch_code, sku_group, size_mapped ), SizeRatio AS ( SELECT sku_group, branch_code, size_mapped, SUM(total_units_sold) AS total_units_per_size, SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group, branch_code) AS total_units_per_sku_group, ROUND((SUM(total_units_sold) / SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group, branch_code)) * 100, 2) AS size_ratio_percentage FROM ItemData GROUP BY sku_group, branch_code, size_mapped ), FinalData AS ( SELECT se.branch_code, se.size, se.size_mapped, se.sku_group, se.logicusercode, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, SUM(se.stock_qty) AS units_on_hand, sc.num_size_available, COALESCE(sr.size_ratio_percentage, 0) AS size_ratio_percentage, SUM(COALESCE(sr.size_ratio_percentage, 0)) OVER (PARTITION BY se.branch_code,se.sku_group) AS sum_size_ratio_percentage_by_sku_group, sum(coalesce(ItemData.total_units_sold,0)) as final_units_sold, sum(coalesce(ItemData.natural_rate_of_sale,0)) as final_natural_rate_of_sale, sum(coalesce(ItemData.seven_day_rate_of_sale,0)) as final_seven_day_rate_of_sale, ItemData.first_sale_date, ItemData.days_elapsed FROM sizeExtract se JOIN sizeCount sc ON se.sku_group = sc.sku_group and se.branch_code=sc.branch_code LEFT JOIN SizeRatio sr ON se.size_mapped = sr.size_mapped and se.branch_code=sr.branch_code and se.sku_group=sr.sku_group LEFT JOIN sizeExtractPivotUp se_pvup ON se.sku_group=se_pvup.sku_group and se.branch_code=se_pvup.branch_code LEFT JOIN ItemData ON se.logicusercode=ItemData.sku and se.branch_code=ItemData.branch_code GROUP BY se.branch_code, se.size, se.size_mapped, se.sku_group, se.logicusercode, sc.num_size_available, sr.size_ratio_percentage, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, ItemData.first_sale_date, ItemData.days_elapsed ), ReplenData AS ( SELECT fd.*, am.id, am.price, am.product_name, UPPER(am.category) AS availability_category, am.xs_units, am.s_units, am.m_units, am.l_units, am.xl_units, am.xxl_units, am.xl3_units, am.xl4_units, am.xl5_units, am.xl6_units, am.na_units, am.xl7_units, am.xl8_units, am.sellable_inventory, am.sku_class, am.num_size_available AS num_size_wh, CAST(sp.priority AS INTEGER) AS priority, CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END AS final_ros, CASE WHEN fd.DAYS_ELAPSED >= 4 THEN ROUND( CASE WHEN ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*10 - fd.UNITS_ON_HAND) < 0 THEN 0 ELSE ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*10 - fd.UNITS_ON_HAND) END,0) ELSE 0 END AS replen_nocap, CASE WHEN SIZE_MAPPED = \'NA\' THEN replen_nocap WHEN replen_nocap >= 6 THEN 6 ELSE replen_nocap END AS replen_cap FROM FinalData fd LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON fd.sku_group = am.sku_group LEFT JOIN store_priority sp ON fd.branch_code = sp.BRANCH_CODE_PRIORITY ), ReplenRatio AS ( SELECT branch_code, sku_group, SUM(replen_nocap) AS total_replen_cap_per_group FROM ReplenData GROUP BY branch_code, sku_group ) SELECT rd.*, CASE WHEN round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) is null THEN 0 ELSE round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) END AS replen_sale_ratio, CASE WHEN rd.SIZE_MAPPED = \'NA\' THEN replen_sale_ratio WHEN replen_sale_ratio < 6 THEN replen_sale_ratio ELSE 6 END AS replen_sale_ratio_capped, CASE WHEN total_replen_cap_per_group >0 AND replen_cap = 0 AND units_on_hand=0 THEN 1 ELSE 0 END AS addl_replen_sizes, (replen_cap+addl_replen_sizes) as replen_1 FROM ReplenData rd LEFT JOIN ReplenRatio rr ON rd.branch_code = rr.branch_code AND rd.sku_group = rr.sku_group ORDER BY rd.priority, rd.units_on_hand DESC; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SRU_RPL_1_MARCH_26 AS WITH inventory_data AS ( SELECT branch_code, COALESCE(REGEXP_SUBSTR(ADDLITEMCODE, \'[^-]+$\'), ADDLITEMCODE) AS size, CASE WHEN POSITION(\'-\' IN ADDLITEMCODE) > 0 THEN LEFT( ADDLITEMCODE, LENGTH(ADDLITEMCODE) - LENGTH(REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), 1, POSITION(\'-\', REVERSE(ADDLITEMCODE)) - 1))) - 1 ) ELSE ADDLITEMCODE END AS sku_group, ADDLITEMCODE, SUM(stock_qty) AS stock_qty, CASE WHEN ADDLITEMCODE LIKE \'SN0%\' OR ADDLITEMCODE LIKE \'4MSFR%\' OR ADDLITEMCODE LIKE \'BP%\' THEN \'NA\' WHEN ADDLITEMCODE LIKE \'SH0%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE date = CURRENT_DATE and ADDLITEMCODE NOT LIKE \'%CB%\' AND ADDLITEMCODE NOT LIKE \'%UNIFORM%\' AND ADDLITEMCODE NOT LIKE \'%HANGER%\' AND ADDLITEMCODE NOT LIKE \'%SHOPPING%\' GROUP BY branch_code, size, sku_group, addlitemcode, size_mapped ), jit_qty AS ( SELECT BRANCH_CODE AS branch_code, \"ITEM CODE\" AS item_code, COALESCE(REGEXP_SUBSTR(\"ITEM CODE\", \'[^-]+$\'), \"ITEM CODE\") AS size, SKU_GROUP AS sku_group, SUM(QTY) AS jit_qty, CASE WHEN \"ITEM CODE\" LIKE \'SN0%\' OR \"ITEM CODE\" LIKE \'4MSFR%\' OR \"ITEM CODE\" LIKE \'BP%\' THEN \'NA\' WHEN \"ITEM CODE\" LIKE \'SH0%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS GROUP BY 1,2,3,4 ), inv_pivot AS ( SELECT branch_code, sku_group, SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END) AS inv_xs, SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END) AS inv_s, SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END) AS inv_m, SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END) AS inv_l, SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END) AS inv_xl, SUM(CASE WHEN size_mapped = \'XXL\' THEN stock_qty ELSE 0 END) AS inv_xxl, SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END) AS inv_3xl, SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END) AS inv_4xl, SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END) AS inv_5xl, SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END) AS inv_6xl, SUM(CASE WHEN size_mapped = \'7XL\' THEN stock_qty ELSE 0 END) AS inv_7xl, SUM(CASE WHEN size_mapped = \'8XL\' THEN stock_qty ELSE 0 END) AS inv_8xl, SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END) AS inv_na FROM inventory_data GROUP BY 1,2 ), jit_pivot AS ( SELECT branch_code, sku_group, SUM(CASE WHEN size_mapped = \'XS\' THEN jit_qty ELSE 0 END) AS jit_xs, SUM(CASE WHEN size_mapped = \'S\' THEN jit_qty ELSE 0 END) AS jit_s, SUM(CASE WHEN size_mapped = \'M\' THEN jit_qty ELSE 0 END) AS jit_m, SUM(CASE WHEN size_mapped = \'L\' THEN jit_qty ELSE 0 END) AS jit_l, SUM(CASE WHEN size_mapped = \'XL\' THEN jit_qty ELSE 0 END) AS jit_xl, SUM(CASE WHEN size_mapped = \'XXL\' THEN jit_qty ELSE 0 END) AS jit_xxl, SUM(CASE WHEN size_mapped = \'3XL\' THEN jit_qty ELSE 0 END) AS jit_3xl, SUM(CASE WHEN size_mapped = \'4XL\' THEN jit_qty ELSE 0 END) AS jit_4xl, SUM(CASE WHEN size_mapped = \'5XL\' THEN jit_qty ELSE 0 END) AS jit_5xl, SUM(CASE WHEN size_mapped = \'6XL\' THEN jit_qty ELSE 0 END) AS jit_6xl, SUM(CASE WHEN size_mapped = \'7XL\' THEN jit_qty ELSE 0 END) AS jit_7xl, SUM(CASE WHEN size_mapped = \'8XL\' THEN jit_qty ELSE 0 END) AS jit_8xl, SUM(CASE WHEN size_mapped = \'NA\' THEN jit_qty ELSE 0 END) AS jit_na FROM jit_qty GROUP BY 1,2 ), all_together AS ( SELECT COALESCE(i.branch_code, j.branch_code) AS branch_code, COALESCE(i.sku_group, j.sku_group) AS sku_group, i.inv_xs, i.inv_s, i.inv_m, i.inv_l, i.inv_xl, i.inv_xxl, i.inv_3xl, i.inv_4xl, i.inv_5xl, i.inv_6xl, i.inv_7xl, i.inv_8xl, i.inv_na, j.jit_xs, j.jit_s, j.jit_m, j.jit_l, j.jit_xl, j.jit_xxl, j.jit_3xl, j.jit_4xl, j.jit_5xl, j.jit_6xl, j.jit_7xl, j.jit_8xl, j.jit_na FROM inv_pivot i FULL OUTER JOIN jit_pivot j ON i.branch_code = j.branch_code AND i.sku_group = j.sku_group ), sales_base AS ( SELECT branch_code, sku, order_date, sum(SUBORDER_QUANTITY) as sold_qty FROM SNITCH_DB.MAPLEMONK.STORE_fact_items_offline WHERE order_date >= DATEADD(day, -60, CURRENT_DATE) AND LOWER(order_status) LIKE \'%process%\' AND DOC_PREFIX NOT IN (\'QCOM\', \'OMS\') group by 1,2,3 ), sales_mapped AS ( SELECT branch_code, order_date, sku, sold_qty, COALESCE(REGEXP_SUBSTR(sku, \'[^-]+$\'), sku) AS size, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN LEFT( sku, LENGTH(sku) - LENGTH(REVERSE(SUBSTRING(REVERSE(sku), 1, POSITION(\'-\', REVERSE(sku)) - 1))) - 1 ) ELSE sku END AS sku_group, CASE WHEN sku LIKE \'SN0%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH0%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM sales_base ), sales_60 AS ( SELECT branch_code, sku_group, size_mapped, SUM(sold_qty) AS sales_qty_60 FROM sales_mapped WHERE order_date >= DATEADD(day, -60, CURRENT_DATE) GROUP BY 1,2,3 ), sales_60_pivot AS ( SELECT branch_code, sku_group, SUM(CASE WHEN size_mapped = \'XS\' THEN sales_qty_60 ELSE 0 END) AS sales60_xs, SUM(CASE WHEN size_mapped = \'S\' THEN sales_qty_60 ELSE 0 END) AS sales60_s, SUM(CASE WHEN size_mapped = \'M\' THEN sales_qty_60 ELSE 0 END) AS sales60_m, SUM(CASE WHEN size_mapped = \'L\' THEN sales_qty_60 ELSE 0 END) AS sales60_l, SUM(CASE WHEN size_mapped = \'XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_xl, SUM(CASE WHEN size_mapped = \'XXL\' THEN sales_qty_60 ELSE 0 END) AS sales60_xxl, SUM(CASE WHEN size_mapped = \'3XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_3xl, SUM(CASE WHEN size_mapped = \'4XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_4xl, SUM(CASE WHEN size_mapped = \'5XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_5xl, SUM(CASE WHEN size_mapped = \'6XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_6xl, SUM(CASE WHEN size_mapped = \'7XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_7xl, SUM(CASE WHEN size_mapped = \'8XL\' THEN sales_qty_60 ELSE 0 END) AS sales60_8xl, SUM(CASE WHEN size_mapped = \'NA\' THEN sales_qty_60 ELSE 0 END) AS sales60_na FROM sales_60 GROUP BY 1,2 ), sales_60_totals AS ( SELECT branch_code, sku_group, (sales60_xs + sales60_s + sales60_m + sales60_l + sales60_xl + sales60_xxl + sales60_3xl + sales60_4xl + sales60_5xl + sales60_6xl + sales60_7xl + sales60_8xl + sales60_na ) AS total_sales_60, sales60_xs, sales60_s, sales60_m, sales60_l, sales60_xl, sales60_xxl, sales60_3xl, sales60_4xl, sales60_5xl, sales60_6xl, sales60_7xl, sales60_8xl, sales60_na FROM sales_60_pivot ), ros_base as ( select branch_code, sku_group, ros from ( with sales_ros_base as ( select branch_code, marketplace_mapped, upper(sku_group) as sku_group, first_order_date, sales_first_15_days, days_since_first_order, total_sales from snitch_db.maplemonk.offline_master ), b2b_base as ( select final_store, case when position(\'-\' in sku) > 0 then left( sku, length(sku) - length(reverse(substring(reverse(sku), 1, position(\'-\', reverse(sku)) - 1))) - 1 ) else sku end as sku_group, max(inwarded_date) as last_inward, count(distinct inwarded_date) as num_orders from snitch_db.maplemonk.b2b_journey where order_name not like \'QC-%\' and inwarded_date < current_date - 3 group by 1,2 ), sales_qty as ( select branch_code, sku, sku_group, order_date, sum(suborder_quantity) as sold_qty from snitch_db.maplemonk.store_fact_items_offline where lower(order_status) like \'%process%\' and doc_prefix not in (\'QCOM\', \'OMS\') group by 1,2,3,4 ), combined as ( select rosb.branch_code, rosb.marketplace_mapped, rosb.sku_group, rosb.sales_first_15_days, rosb.days_since_first_order, rosb.total_sales, coalesce(b2bb.last_inward, rosb.first_order_date) as inward_date, coalesce(b2bb.num_orders, 0) as num_orders, sqty.order_date, sqty.sold_qty from sales_ros_base rosb left join b2b_base b2bb on rosb.marketplace_mapped = b2bb.final_store and rosb.sku_group = b2bb.sku_group left join sales_qty sqty on rosb.branch_code = sqty.branch_code and rosb.sku_group = sqty.sku_group and sqty.order_date >= coalesce(b2bb.last_inward, rosb.first_order_date) ), sku_ros as ( select branch_code, marketplace_mapped, sku_group, inward_date, num_orders, days_since_first_order, total_sales, sales_first_15_days, sum(coalesce(sold_qty, 0)) as qty_sold_since_last_inward, datediff(day, inward_date, current_date) as days_since_last_inward, case when num_orders > 1 then sum(coalesce(sold_qty, 0)) / nullif(datediff(day, inward_date, current_date), 0) when days_since_first_order < 15 then total_sales / nullif(days_since_first_order, 0) else sales_first_15_days / 15 end as ros from combined group by branch_code, marketplace_mapped, sku_group, inward_date, num_orders, days_since_first_order, total_sales, sales_first_15_days ) select * from sku_ros) ), sales_metrics AS ( SELECT t.branch_code, t.sku_group, t.total_sales_60, IFF(t.total_sales_60 = 0, 0, t.sales60_xs / t.total_sales_60) AS ratio_xs_60, IFF(t.total_sales_60 = 0, 0, t.sales60_s / t.total_sales_60) AS ratio_s_60, IFF(t.total_sales_60 = 0, 0, t.sales60_m / t.total_sales_60) AS ratio_m_60, IFF(t.total_sales_60 = 0, 0, t.sales60_l / t.total_sales_60) AS ratio_l_60, IFF(t.total_sales_60 = 0, 0, t.sales60_xl / t.total_sales_60) AS ratio_xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_xxl / t.total_sales_60) AS ratio_xxl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_3xl / t.total_sales_60) AS ratio_3xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_4xl / t.total_sales_60) AS ratio_4xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_5xl / t.total_sales_60) AS ratio_5xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_6xl / t.total_sales_60) AS ratio_6xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_7xl / t.total_sales_60) AS ratio_7xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_8xl / t.total_sales_60) AS ratio_8xl_60, IFF(t.total_sales_60 = 0, 0, t.sales60_na / t.total_sales_60) AS ratio_na_60, rb.ros FROM sales_60_totals t LEFT JOIN ros_base rb ON t.branch_code = rb.branch_code AND t.sku_group = rb.sku_group ), category_map as ( SELECT sku_group, category FROM ( SELECT sku_group, category, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY category) AS rn FROM snitch_db.maplemonk.metafields_data ) t WHERE rn = 1 ) SELECT a.*, CASE WHEN a.sku_group LIKE \'%4MSS4717%\' THEN \'Shirts\' when a.sku_group like \'%4MSS4718%\' THEN \'Shirts\' ELSE cm.category END AS category, sm.total_sales_60, sm.ratio_xs_60, sm.ratio_s_60, sm.ratio_m_60, sm.ratio_l_60, sm.ratio_xl_60, sm.ratio_xxl_60, sm.ratio_3xl_60, sm.ratio_4xl_60, sm.ratio_5xl_60, sm.ratio_6xl_60, sm.ratio_7xl_60, sm.ratio_8xl_60, sm.ros FROM all_together a LEFT JOIN sales_metrics sm ON a.branch_code = sm.branch_code AND a.sku_group = sm.sku_group left join category_map cm on a.sku_group = cm.sku_group ;",
                    "transaction": true
                }
            ) }}
